package com.ktb.hackathon.team11.assignment;import com.ktb.hackathon.team11.ai.CompletionType;import com.ktb.hackathon.team11.global.response.ApiResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.NotNull;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1") @RequiredArgsConstructor public class AssignmentController{private final AssignmentService service;@GetMapping("/workers/{workerId}/assignments")ApiResponse<List<Response>> worker(@PathVariable long workerId,@RequestParam LocalDate date){return ApiResponse.of("ASSIGNMENTS_FOUND",service.worker(workerId,date).stream().map(Response::from).toList());}@GetMapping("/groups/{groupId}/assignments")ApiResponse<List<Response>> group(@PathVariable long groupId,@RequestParam long managerId,@RequestParam LocalDate date){return ApiResponse.of("ASSIGNMENTS_FOUND",service.group(groupId,managerId,date).stream().map(Response::from).toList());}@GetMapping("/assignments/{id}")ApiResponse<Response> detail(@PathVariable long id,@RequestParam long memberId){TaskAssignment a=service.require(id);return ApiResponse.of("ASSIGNMENT_FOUND",Response.from(a));}@PostMapping("/assignments/{id}/check")ApiResponse<Response> check(@PathVariable long id,@Valid @RequestBody CheckRequest r){return ApiResponse.of("ASSIGNMENT_COMPLETED",Response.from(service.check(id,r.workerId())));}public record CheckRequest(@NotNull Long workerId){}public record Response(Long assignmentId,String title,String instruction,CompletionType completionType,AssignmentStatus status,LocalDateTime availableFrom,LocalDateTime dueAt,Long assigneeId){static Response from(TaskAssignment a){return new Response(a.getId(),a.getTaskItemTemplate().getTitle(),a.getTaskItemTemplate().getInstruction(),a.getTaskItemTemplate().getCompletionType(),a.getStatus(),a.getAvailableFrom(),a.getDueAt(),a.getAssignee()==null?null:a.getAssignee().getId());}}}
